function Table() {
  const ref = useRef<HTMLDivElement | null>(null);
  const [offsetX, setOffsetX] = useState(0);

  useEffect(() => {
    const update = () => {
      const el = ref.current;
      if (!el) return;
      const rect = el.getBoundingClientRect();
      const viewportH = window.innerHeight;
      const start = viewportH * 0.9;
      const end = -rect.height * 0.45;
      const raw = (start - rect.top) / (start - end);
      const progress = Math.max(0, Math.min(1, raw));
      setOffsetX(-360 * progress);
    };

    update();
    window.addEventListener('scroll', update, { passive: true });
    window.addEventListener('resize', update);
    return () => {
      window.removeEventListener('scroll', update);
      window.removeEventListener('resize', update);
    };
  }, []);

  return (
    <div
      ref={ref}
      className="absolute content-stretch flex flex-col items-start left-[calc(16.67%+85px)] p-[10px] top-[4452px] w-[1400px] will-change-transform"
      data-name="table 1"
      style={{ transform: `translateX(${offsetX}px)` }}
    >
      <Frame30 />
    </div>
  );
}

